insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('como-reconocer-un-correo-falso-antes-de-abrirlo','tecnologia',array['sociedad']::text[],'¿Cómo reconocer un correo falso antes de abrirlo?','Aprende a distinguir un correo legítimo de uno falso observando pistas concretas, y convierte lo que descubras en una guía que cualquier persona pueda usar.','Guía','~8 h',8,array['Seguridad digital','Prevención','Análisis de casos']::text[],array['resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas ingenieria de software computacion e informatica derecho comunicaciones educacion administracion contabilidad seguridad de la informacion. analisis de casos. comunicacion clara para publico no tecnico. pensamiento critico. diseno de materiales educativos. documento o presentacion. hoja de calculo para clasificar los ejemplos. herramientas para disenar infografias.',$f1fb543${"id": "como-reconocer-un-correo-falso-antes-de-abrirlo", "area": "tecnologia", "areas2": ["sociedad"], "titulo": "¿Cómo reconocer un correo falso antes de abrirlo?", "resumen": "Aprende a distinguir un correo legítimo de uno falso observando pistas concretas, y convierte lo que descubras en una guía que cualquier persona pueda usar.", "tipo": "Guía", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Seguridad digital", "Prevención", "Análisis de casos"], "intencion": ["resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con correos inventados o con ejemplos que instituciones y empresas publican para enseñar a reconocer fraudes; no hace falta recibir ni enviar correos reales.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Derecho", "Comunicaciones", "Educación", "Administración", "Contabilidad"], "problema": ["Los correos falsos que imitan a un banco, a una empresa de entregas o a la propia institución educativa llegan cada día, y los más convincentes ya no tienen errores de ortografía ni logos mal hechos. Una persona apurada puede entregar sus claves en segundos.", "La mayoría de las guías dicen «desconfía» sin explicar en qué fijarse. Sin criterios concretos, las personas terminan desconfiando de todo o de nada."], "desarrollar": ["Reúne entre 10 y 15 ejemplos de correos, mitad legítimos y mitad falsos, todos inventados o tomados de material educativo público. Para cada uno identifica las pistas que delatan el engaño: la dirección del remitente, el destino real de los enlaces, el tono de urgencia, los adjuntos y lo que se pide.", "Con eso arma un recorrido de preguntas que cualquiera pueda hacerse antes de hacer clic, y pruébalo con alguien cercano para ver dónde se confunde. El resultado puede ser una guía de una página, una infografía o un cuestionario de práctica."], "ampliaciones": [{"titulo": "Un nivel más difícil", "aporta": "agrega casos dirigidos a una persona concreta, que mencionan su nombre o su institución y parecen mucho más creíbles."}, {"titulo": "Qué hacer después", "aporta": "suma a la guía los pasos para reaccionar si ya hiciste clic: cambiar claves, avisar y revisar movimientos."}, {"titulo": "Un revisor de pistas", "aporta": "automatiza la revisión de las señales más fáciles de medir, como la diferencia entre el texto de un enlace y su destino."}], "objetivos": ["Identificar las pistas que delatan un correo fraudulento.", "Clasificar los casos según su nivel de dificultad.", "Elaborar criterios claros y fáciles de recordar.", "Probar la guía con otras personas y ajustarla según lo que no entiendan.", "Presentar el resultado en un formato que se pueda compartir."], "habilidades": ["Seguridad de la información.", "Análisis de casos.", "Comunicación clara para público no técnico.", "Pensamiento crítico.", "Diseño de materiales educativos."], "herramientas": ["Documento o presentación.", "Hoja de cálculo para clasificar los ejemplos.", "Herramientas para diseñar infografías."], "lineamientos": ["Cuidados: trabaja solo con correos ficticios o de material educativo público. No envíes correos falsos a otras personas, ni siquiera como prueba, y no publiques mensajes reales que contengan datos de alguien.", "Presenta las pistas como ayuda y no como garantía: ningún criterio detecta todos los engaños."], "otroSector": "El mismo enfoque sirve para entrenar al personal de una oficina, de un negocio pequeño o de una institución pública a reconocer mensajes fraudulentos por mensajería o por llamada."}$f1fb543$::jsonb,0),
('cuanto-tardaria-en-adivinarse-tu-contrasena','tecnologia',array['ciencias']::text[],'¿Cuánto tardaría en adivinarse tu contraseña?','Estima con matemática sencilla cuánto tardaría un atacante en adivinar distintos tipos de contraseña, y descubre por qué unas aguantan años y otras segundos.','Análisis','~8 h',8,array['Seguridad digital','Matemática','Hábitos digitales']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software computacion e informatica matematica estadistica educacion contabilidad administracion combinatoria y potencias. seguridad de la informacion. uso de hoja de calculo. visualizacion de datos. redaccion de recomendaciones claras. hoja de calculo. calculadora cientifica o lenguaje de programacion sencillo, si quieres automatizar. herramienta para hacer graficos.',$f5e3edc${"id": "cuanto-tardaria-en-adivinarse-tu-contrasena", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "¿Cuánto tardaría en adivinarse tu contraseña?", "resumen": "Estima con matemática sencilla cuánto tardaría un atacante en adivinar distintos tipos de contraseña, y descubre por qué unas aguantan años y otras segundos.", "tipo": "Análisis", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Seguridad digital", "Matemática", "Hábitos digitales"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: usa solo contraseñas inventadas con la misma forma que las tuyas; nunca escribas ni compartas una real.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Matemática", "Estadística", "Educación", "Contabilidad", "Administración"], "problema": ["Casi todos hemos escuchado que una contraseña debe ser «larga y con símbolos», pero pocos saben cuánto cambia la seguridad con cada carácter que se añade o con cada hábito, como repetirla en varios sitios.", "Sin esa noción, las personas eligen entre reglas que no entienden: cambian la clave cada mes por obligación pero la hacen más fácil de recordar y, por lo tanto, de adivinar."], "desarrollar": ["Define 8 contraseñas ficticias de distinto tipo: corta, solo letras, con una palabra común, una frase larga, con números previsibles, etc. Calcula cuántas combinaciones posibles tiene cada una y cuánto tardaría en recorrerlas un equipo que prueba, por ejemplo, mil millones de intentos por segundo.", "Compara los resultados en una tabla y un gráfico, y explica con tus palabras qué hábitos aportan más seguridad. El resultado puede ser una guía de una página con la tabla como protagonista."], "ampliaciones": [{"titulo": "Ataques más listos", "aporta": "explica por qué una contraseña formada por una palabra del diccionario cae mucho más rápido de lo que dice la cuenta de combinaciones."}, {"titulo": "Un medidor sencillo", "aporta": "construye una hoja o una pequeña página que, sin guardar nada, muestre el tiempo estimado para una clave inventada."}, {"titulo": "Más allá de la clave", "aporta": "analiza cuánto suma la verificación en dos pasos y qué cambia si una clave se filtra."}], "objetivos": ["Calcular el número de combinaciones de distintos tipos de contraseña.", "Estimar tiempos de ataque bajo supuestos claros.", "Distinguir entre longitud, variedad y previsibilidad.", "Traducir resultados numéricos a recomendaciones concretas.", "Comunicar el resultado sin tecnicismos."], "habilidades": ["Combinatoria y potencias.", "Seguridad de la información.", "Uso de hoja de cálculo.", "Visualización de datos.", "Redacción de recomendaciones claras."], "herramientas": ["Hoja de cálculo.", "Calculadora científica o lenguaje de programación sencillo, si quieres automatizar.", "Herramienta para hacer gráficos."], "lineamientos": ["Cuidados: nunca ingreses tus contraseñas reales en una página, hoja o programa, ni siquiera para «probarlas». Todo el ejercicio se hace con claves inventadas.", "Aclara que las estimaciones dependen de supuestos y que los números reales cambian con la tecnología del atacante."], "otroSector": "La misma lógica de «cuánto tardaría en adivinarse» se aplica a códigos de acceso, PIN de tarjetas, números de pedido o cualquier identificador que alguien podría intentar adivinar."}$f5e3edc$::jsonb,1),
('tus-archivos-olvidados-cuanto-espacio-ocupa-lo-que-ya-no-usas','tecnologia',array['ambiente']::text[],'Tus archivos olvidados: ¿cuánto espacio ocupa lo que ya no usas?','Mide cuánto espacio digital ocupa lo que ya no usas y propón un método para ordenar y liberar sin perder lo importante.','Análisis','~8 h',8,array['Organización','Datos','Consumo responsable']::text[],array['investigar','resolver','otro-sector']::text[],'propios','sin','ingenieria de sistemas ingenieria ambiental computacion e informatica administracion gestion de la informacion educacion comunicaciones organizacion de la informacion. uso de hoja de calculo. habitos digitales responsables. analisis de datos propios. redaccion de guias claras. explorador de archivos y herramientas de almacenamiento del sistema. hoja de calculo. documento de texto.',$ffcd07d${"id": "tus-archivos-olvidados-cuanto-espacio-ocupa-lo-que-ya-no-usas", "area": "tecnologia", "areas2": ["ambiente"], "titulo": "Tus archivos olvidados: ¿cuánto espacio ocupa lo que ya no usas?", "resumen": "Mide cuánto espacio digital ocupa lo que ya no usas y propón un método para ordenar y liberar sin perder lo importante.", "tipo": "Análisis", "tiempo": "~8 h", "horas": 8, "etiquetas": ["Organización", "Datos", "Consumo responsable"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios: revisa tus propios archivos y almacenamiento; no hace falta mirar datos de otras personas.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Ambiental", "Computación e Informática", "Administración", "Gestión de la Información", "Educación", "Comunicaciones"], "problema": ["Los celulares, las computadoras y las cuentas en la nube se llenan de fotos repetidas, descargas olvidadas y versiones antiguas de documentos. Cuando el espacio se acaba, la reacción habitual es pagar por más almacenamiento en lugar de ordenar.", "Guardar de más también tiene un costo: los centros de datos consumen energía para conservar archivos que nadie vuelve a abrir."], "desarrollar": ["Elige un dispositivo o una cuenta tuya y haz un inventario por tipo de archivo: fotos, videos, documentos, descargas y aplicaciones. Mide cuánto ocupa cada grupo, cuánto no has abierto en más de un año y cuántos archivos son repetidos.", "Con esos números diseña un método de orden de tres pasos, que decida qué conservar, qué archivar y qué eliminar, y pruébalo en una parte pequeña. El resultado puede ser una hoja con el antes y el después y una guía de una página."], "ampliaciones": [{"titulo": "Un hábito mensual", "aporta": "convierte el método en una rutina de diez minutos y comprueba si logras mantenerla durante un mes."}, {"titulo": "Los repetidos", "aporta": "compara herramientas que detectan archivos duplicados y qué tan fiables son."}, {"titulo": "El costo oculto", "aporta": "estima el costo en energía y dinero de conservar lo que nunca vuelves a abrir."}], "objetivos": ["Medir el uso de espacio por tipo de archivo.", "Identificar archivos repetidos y sin uso.", "Definir criterios claros para conservar, archivar y eliminar.", "Probar el método y ajustarlo con los resultados.", "Comunicar los hábitos de orden de forma sencilla."], "habilidades": ["Organización de la información.", "Uso de hoja de cálculo.", "Hábitos digitales responsables.", "Análisis de datos propios.", "Redacción de guías claras."], "herramientas": ["Explorador de archivos y herramientas de almacenamiento del sistema.", "Hoja de cálculo.", "Documento de texto."], "lineamientos": ["Cuidados: trabaja solo con tus propios archivos y haz una copia de respaldo antes de eliminar nada.", "No publiques capturas que muestren documentos o fotos personales."], "otroSector": "El mismo método sirve para ordenar los archivos compartidos de un equipo, de una oficina o de una institución educativa."}$ffcd07d$::jsonb,2),
('que-pasa-con-tu-vida-digital-si-pierdes-el-celular','tecnologia',array['sociedad']::text[],'¿Qué pasa con tu vida digital si pierdes el celular?','Investiga qué ocurriría con tus cuentas, fotos, contactos y pagos si tu celular o tu laptop se perdieran o fueran robados mañana mismo, y qué podrías hacer hoy para que el golpe sea mucho menor.','Guía','~10 h',10,array['Seguridad digital','Prevención']::text[],array['resolver','otro-sector']::text[],'propios','sin','ingenieria de sistemas ingenieria de software derecho psicologia administracion educacion comunicaciones seguridad de la informacion. gestion de riesgos personales. organizacion y clasificacion de datos. redaccion de instrucciones claras. pensamiento preventivo. hoja de calculo o editor de documentos. herramientas de diagramas de flujo. gestores de contrasenas y respaldos en la nube, solo como parte del analisis.',$fd3606c${"id": "que-pasa-con-tu-vida-digital-si-pierdes-el-celular", "area": "tecnologia", "areas2": ["sociedad"], "titulo": "¿Qué pasa con tu vida digital si pierdes el celular?", "resumen": "Investiga qué ocurriría con tus cuentas, fotos, contactos y pagos si tu celular o tu laptop se perdieran o fueran robados mañana mismo, y qué podrías hacer hoy para que el golpe sea mucho menor.", "tipo": "Guía", "tiempo": "~10 h", "horas": 10, "etiquetas": ["Seguridad digital", "Prevención"], "intencion": ["resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes hacer el ejercicio con tu propio teléfono sin compartir información sensible, o inventar un perfil de usuario con sus cuentas y aplicaciones.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Derecho", "Psicología", "Administración", "Educación", "Comunicaciones"], "problema": ["El celular concentra correos, redes sociales, aplicaciones bancarias, billeteras digitales, códigos de verificación y conversaciones importantes. Perderlo no es solo perder un aparato: es perder el acceso a medio mundo digital, y a veces dejar ese acceso en manos de otra persona.", "Muchas personas descubren recién en ese momento que no sabían qué cuentas estaban abiertas, que sus códigos de verificación llegaban solo a ese teléfono o que no tenían una copia de sus archivos más importantes."], "desarrollar": ["Un inventario sencillo de las cuentas y servicios que dependen del dispositivo, clasificados por nivel de riesgo, junto con un plan de acción en dos partes: qué hacer antes de que ocurra una pérdida y qué hacer en la primera hora después.", "El resultado puede ser una lista de verificación, una guía visual o una hoja de cálculo que cualquier persona pueda adaptar a su caso."], "ampliaciones": [{"titulo": "Para quien más lo necesita", "aporta": "adapta la guía a una persona mayor o a un negocio pequeño cuyo celular concentra pagos y pedidos."}, {"titulo": "Un simulacro", "aporta": "practica con una persona voluntaria qué haría en la primera hora y mide qué paso le cuesta más."}, {"titulo": "Un formato para compartir", "aporta": "transforma el plan en una tarjeta o un cartel que pueda guardarse en casa y enviarse al grupo familiar."}], "objetivos": ["Identificar qué cuentas, datos y servicios dependen de un dispositivo.", "Clasificar la información según el daño que causaría su pérdida o exposición.", "Diseñar medidas preventivas sencillas, como respaldos y verificación en dos pasos.", "Elaborar un plan de respuesta ordenado para la primera hora tras una pérdida.", "Presentar la guía en un formato que otras personas puedan aplicar sin ayuda."], "habilidades": ["Seguridad de la información.", "Gestión de riesgos personales.", "Organización y clasificación de datos.", "Redacción de instrucciones claras.", "Pensamiento preventivo."], "herramientas": ["Hoja de cálculo o editor de documentos.", "Herramientas de diagramas de flujo.", "Gestores de contraseñas y respaldos en la nube, solo como parte del análisis."], "lineamientos": ["No incluyas contraseñas, códigos, números de cuenta ni datos personales reales en el material que compartas: trabaja con categorías y ejemplos genéricos. Si pruebas el plan con otras personas, hazlo únicamente con su consentimiento y sin acceder a sus cuentas.", "Presenta las recomendaciones como buenas prácticas generales y no como garantía de seguridad total."], "otroSector": "La misma idea puede utilizarse para planes de continuidad ante la pérdida de equipos en pequeñas empresas, consultorios, estudios profesionales o equipos de trabajo remoto."}$fd3606c$::jsonb,3),
('como-viaja-un-mensaje-por-internet-paso-a-paso','tecnologia',array['educacion']::text[],'¿Cómo viaja un mensaje por Internet, paso a paso?','Sigue el recorrido de un mensaje desde tu pantalla hasta otra persona y explícalo en un mapa visual que cualquiera pueda entender.','Guía','~12 h',12,array['Redes','Comunicación','Explicación visual']::text[],array['resolver','otro-sector']::text[],'propios','sin','ingenieria de sistemas ingenieria de software computacion e informatica telecomunicaciones educacion comunicaciones diseno grafico conceptos basicos de redes. diagnostico de conexiones. explicacion de procesos tecnicos. diseno de esquemas. comunicacion para publicos no tecnicos. herramientas de diagnostico de red del sistema. editor de diagramas o presentaciones. documento de texto.',$f4495ee${"id": "como-viaja-un-mensaje-por-internet-paso-a-paso", "area": "tecnologia", "areas2": ["educacion"], "titulo": "¿Cómo viaja un mensaje por Internet, paso a paso?", "resumen": "Sigue el recorrido de un mensaje desde tu pantalla hasta otra persona y explícalo en un mapa visual que cualquiera pueda entender.", "tipo": "Guía", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Redes", "Comunicación", "Explicación visual"], "intencion": ["resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios: puedes seguir el recorrido de tu propia conexión con herramientas sencillas del sistema, sin revisar datos de otras personas.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Telecomunicaciones", "Educación", "Comunicaciones", "Diseño Gráfico"], "problema": ["Enviamos mensajes, abrimos páginas y hacemos videollamadas sin saber qué pasa entre nuestro dispositivo y el de la otra persona. Cuando algo falla, no hay forma de saber en qué parte del camino ocurrió.", "Los textos técnicos describen esos pasos con términos que asustan a quien recién empieza, y muchos esquemas de redes son difíciles de seguir sin una explicación guiada."], "desarrollar": ["Elige un caso simple, como abrir una página web o enviar un mensaje, y reconstruye sus etapas: tu dispositivo, la red local, el proveedor de Internet, los servidores intermedios y el destino. Usa herramientas básicas de diagnóstico que ya trae tu sistema para ver parte del recorrido real.", "Dibuja el camino como un mapa con cuatro o cinco paradas y explica en una o dos frases qué ocurre en cada una. El resultado puede ser una infografía o una presentación breve pensada para alguien sin formación técnica."], "ampliaciones": [{"titulo": "Cuando algo se rompe", "aporta": "añade al mapa los puntos donde suele fallar el servicio y cómo se nota cada falla."}, {"titulo": "Dos recorridos distintos", "aporta": "compara cómo viaja un mensaje de texto con una videollamada y por qué una se corta más fácilmente."}, {"titulo": "Una explicación para niños", "aporta": "adapta el mapa para estudiantes de colegio con una comparación cotidiana, como el correo postal."}], "objetivos": ["Describir las etapas principales del recorrido de un mensaje.", "Reconocer los equipos y servicios que intervienen.", "Relacionar fallas comunes con la etapa donde ocurren.", "Explicar el proceso con un lenguaje claro.", "Diseñar un material visual que pueda usarse sin ayuda."], "habilidades": ["Conceptos básicos de redes.", "Diagnóstico de conexiones.", "Explicación de procesos técnicos.", "Diseño de esquemas.", "Comunicación para públicos no técnicos."], "herramientas": ["Herramientas de diagnóstico de red del sistema.", "Editor de diagramas o presentaciones.", "Documento de texto."], "lineamientos": ["Trabaja con tu propia conexión y evita publicar direcciones o datos de tu casa o de tu institución en el material final.", "Si simplificas un concepto, aclara que es una simplificación para que nadie la tome como descripción completa."], "otroSector": "El mismo recorrido puede explicarse para el correo electrónico, los pagos por internet, la entrega de una compra en línea o el envío de una factura electrónica."}$f4495ee$::jsonb,4),
('como-trabajar-en-equipo-sin-pisarse-los-archivos','tecnologia',array['educacion']::text[],'¿Cómo trabajar en equipo sin pisarse los archivos?','Diseña una forma sencilla de compartir, versionar y respaldar los archivos de un equipo para que nadie sobrescriba el trabajo de otro ni lo pierda.','Guía','~12 h',12,array['Trabajo en equipo','Versiones','Copias de respaldo']::text[],array['resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas ingenieria de software computacion e informatica administracion educacion comunicaciones contabilidad arquitectura gestion de la informacion. control de versiones. trabajo colaborativo. redaccion de procedimientos. prevencion de riesgos. servicios de almacenamiento compartido. hoja de calculo o documento para registrar los casos. opcionalmente, una herramienta de control de versiones.',$f27cac3${"id": "como-trabajar-en-equipo-sin-pisarse-los-archivos", "area": "tecnologia", "areas2": ["educacion"], "titulo": "¿Cómo trabajar en equipo sin pisarse los archivos?", "resumen": "Diseña una forma sencilla de compartir, versionar y respaldar los archivos de un equipo para que nadie sobrescriba el trabajo de otro ni lo pierda.", "tipo": "Guía", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Trabajo en equipo", "Versiones", "Copias de respaldo"], "intencion": ["resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: usa un trabajo de equipo simulado con archivos inventados.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Administración", "Educación", "Comunicaciones", "Contabilidad", "Arquitectura"], "problema": ["En un trabajo grupal es común que dos personas editen el mismo archivo a la vez, que una versión «final» se confunda con otra o que alguien borre algo importante sin darse cuenta. El resultado son horas perdidas rehaciendo lo que ya estaba hecho.", "Muchos equipos descubren que no tienen una copia de respaldo justo el día que la necesitan."], "desarrollar": ["Simula un trabajo de equipo de cuatro personas y registra los errores típicos: archivos con nombres confusos, ediciones simultáneas y versiones perdidas. Diseña un conjunto de reglas simples sobre cómo nombrar los archivos, quién edita qué, cuándo se guarda una versión y dónde está la copia de respaldo.", "Pon a prueba las reglas con una simulación de una semana y anota qué problemas desaparecen y cuáles quedan. El resultado puede ser una guía de una página y una plantilla de carpetas lista para usar."], "ampliaciones": [{"titulo": "Un caso real", "aporta": "aplícalo a un trabajo de equipo verdadero con permiso de tus compañeros y mide cuántos conflictos evita."}, {"titulo": "Recuperarse de un error", "aporta": "ensaya qué hacer cuando alguien sobrescribe un archivo y mide cuánto cuesta recuperarlo."}, {"titulo": "Una herramienta de versiones", "aporta": "compara una forma manual de versionar con una herramienta que lo haga automáticamente."}], "objetivos": ["Identificar las causas de los conflictos de archivos en un equipo.", "Definir reglas claras de nombres, versiones y responsables.", "Diseñar una política de copias de respaldo.", "Probar las reglas en una simulación.", "Escribir una guía que cualquier equipo pueda aplicar."], "habilidades": ["Gestión de la información.", "Control de versiones.", "Trabajo colaborativo.", "Redacción de procedimientos.", "Prevención de riesgos."], "herramientas": ["Servicios de almacenamiento compartido.", "Hoja de cálculo o documento para registrar los casos.", "Opcionalmente, una herramienta de control de versiones."], "lineamientos": ["Mantén las reglas lo bastante simples para que el equipo las siga cuando esté apurado.", "Si lo pruebas con un equipo real, avísales y pide su permiso antes de revisar sus archivos."], "otroSector": "Las mismas reglas sirven en oficinas contables, estudios de diseño, consultorios, redacciones y cualquier lugar donde varias personas toquen los mismos documentos."}$f27cac3$::jsonb,5),
('como-sabes-que-un-archivo-no-fue-alterado','tecnologia',array['derecho']::text[],'¿Cómo sabes que un archivo no fue alterado?','Descubre cómo una huella digital permite comprobar que un archivo es exactamente el mismo, y qué pasa cuando alguien lo modifica.','Investigación','~12 h',12,array['Seguridad digital','Integridad','Verificación']::text[],array['investigar','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ciberseguridad derecho contabilidad auditoria computacion e informatica archivistica seguridad de la informacion. integridad de datos. uso de herramientas del sistema. pensamiento critico. redaccion de guias claras. herramientas del sistema para calcular huellas. hoja de calculo o documento. opcionalmente un lenguaje de programacion.',$f4644b1${"id": "como-sabes-que-un-archivo-no-fue-alterado", "area": "tecnologia", "areas2": ["derecho"], "titulo": "¿Cómo sabes que un archivo no fue alterado?", "resumen": "Descubre cómo una huella digital permite comprobar que un archivo es exactamente el mismo, y qué pasa cuando alguien lo modifica.", "tipo": "Investigación", "tiempo": "~12 h", "horas": 12, "etiquetas": ["Seguridad digital", "Integridad", "Verificación"], "intencion": ["investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: crea archivos de prueba y modifícalos tú mismo para ver qué cambia.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ciberseguridad", "Derecho", "Contabilidad", "Auditoría", "Computación e Informática", "Archivística"], "problema": ["Cuando recibimos un documento, un instalador o una prueba, casi nunca podemos saber si alguien lo cambió en el camino. Un contrato modificado en una coma o un programa con algo añadido pueden pasar sin que nadie lo note.", "Existe una técnica sencilla que genera una huella digital única de cada archivo, pero casi nadie sabe cómo se usa ni qué tan fiable es."], "desarrollar": ["Crea cinco archivos de prueba y obtén la huella digital de cada uno con una herramienta del sistema. Cambia una coma, una letra o un píxel, vuelve a calcularla y observa cuánto cambia.", "Luego plantea una situación en la que dos personas se envían un archivo y acuerdan cómo verificar que llegó intacto. El resultado puede ser una guía de dos páginas con ejemplos, una explicación sobre sus límites y una demostración."], "ampliaciones": [{"titulo": "Qué no protege", "aporta": "explica por qué la huella no dice quién escribió el archivo ni si es verdadero."}, {"titulo": "Dos archivos, una huella", "aporta": "investiga qué se sabe sobre huellas repetidas y por qué algunas técnicas dejaron de ser seguras."}, {"titulo": "Una herramienta propia", "aporta": "crea una pequeña herramienta que compare dos carpetas y señale qué archivos cambiaron."}], "objetivos": ["Generar huellas digitales de archivos.", "Observar su sensibilidad a pequeños cambios.", "Plantear un procedimiento de verificación entre dos personas.", "Explicar sus límites.", "Comunicar el concepto a un público general."], "habilidades": ["Seguridad de la información.", "Integridad de datos.", "Uso de herramientas del sistema.", "Pensamiento crítico.", "Redacción de guías claras."], "herramientas": ["Herramientas del sistema para calcular huellas.", "Hoja de cálculo o documento.", "Opcionalmente un lenguaje de programación."], "lineamientos": ["Trabaja con archivos de prueba que puedas compartir.", "No afirmes que la huella digital garantiza autoría o legalidad: solo comprueba que el contenido no cambió."], "otroSector": "La misma técnica se usa para verificar copias de respaldo, evidencias digitales, actualizaciones de programas, documentos escaneados y entregas de trabajos."}$f4644b1$::jsonb,6),
('que-aprender-cuando-se-cae-un-servicio-digital-que-todos-usan','tecnologia',array['sociedad']::text[],'¿Qué aprender cuando se cae un servicio digital que todos usan?','Investiga qué ocurre cuando una aplicación, plataforma o servicio de uso masivo deja de funcionar durante horas, cómo se detecta y se resuelve el problema, y qué decisiones de comunicación y de diseño pueden reducir el daño la próxima vez.','Investigación','~15 h',15,array['Sistemas','Gestión de crisis','Análisis de casos']::text[],array['investigar','otro-sector']::text[],'publicos','sin','ingenieria de sistemas ingenieria de software ingenieria industrial administracion comunicaciones ingenieria de telecomunicaciones ciencia de datos analisis de casos y de causas. pensamiento sistemico. lectura critica de fuentes tecnicas. gestion de crisis y comunicacion. redaccion de informes claros. buscadores y fuentes publicas. herramientas de lineas de tiempo y diagramas. hoja de calculo para ordenar los hechos. editor de documentos o presentaciones.',$fcc6c24${"id": "que-aprender-cuando-se-cae-un-servicio-digital-que-todos-usan", "area": "tecnologia", "areas2": ["sociedad"], "titulo": "¿Qué aprender cuando se cae un servicio digital que todos usan?", "resumen": "Investiga qué ocurre cuando una aplicación, plataforma o servicio de uso masivo deja de funcionar durante horas, cómo se detecta y se resuelve el problema, y qué decisiones de comunicación y de diseño pueden reducir el daño la próxima vez.", "tipo": "Investigación", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Sistemas", "Gestión de crisis", "Análisis de casos"], "intencion": ["investigar", "otro-sector"], "datos": "publicos", "datosTexto": "públicos: puedes trabajar con informes, comunicados y explicaciones que las propias empresas o instituciones publican después de una caída de sus servicios, o con un caso inventado.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Administración", "Comunicaciones", "Ingeniería de Telecomunicaciones", "Ciencia de Datos"], "problema": ["Cuando se cae un servicio que millones de personas usan, el efecto va mucho más allá de lo técnico: se interrumpen pagos, clases, trabajo, comunicaciones y negocios enteros. En esos momentos, lo que más se nota es la falta de información clara sobre qué pasó, cuánto va a durar y qué hacer mientras tanto.", "Muchas organizaciones publican luego un informe de lo ocurrido, pero rara vez se lee con ojo crítico. Estos documentos contienen información valiosa sobre cómo una falla pequeña puede crecer, qué señales se ignoraron y qué cambios se hicieron después."], "desarrollar": ["Elige un incidente público o inventa uno, y reconstruye su historia en una línea de tiempo: qué falló, cuándo se detectó, qué se hizo, cuánto tardó la recuperación y cómo se comunicó a las personas afectadas.", "Luego identifica las causas principales, qué medidas de prevención se anunciaron y qué lecciones podría aplicar cualquier equipo que mantenga un sistema, incluso uno pequeño.", "El resultado puede ser un informe breve, una presentación o un análisis visual que explique el caso de forma clara a alguien sin formación técnica."], "ampliaciones": [{"titulo": "Otro caso", "aporta": "compara dos incidentes de servicios distintos y qué aprendió cada organización."}, {"titulo": "Un simulacro a escala pequeña", "aporta": "imagina que se cae el sistema de una tienda o de un club y escribe el comunicado que enviarías."}, {"titulo": "Una guía para equipos pequeños", "aporta": "resume las lecciones en una lista de verificación que cualquier equipo pueda usar."}], "objetivos": ["Reconstruir cronológicamente un incidente a partir de fuentes públicas.", "Distinguir entre causas técnicas, de proceso y de comunicación.", "Evaluar qué tan clara y oportuna fue la información dada a las personas afectadas.", "Extraer lecciones aplicables a otros sistemas y organizaciones.", "Presentar el caso de manera comprensible para un público general."], "habilidades": ["Análisis de casos y de causas.", "Pensamiento sistémico.", "Lectura crítica de fuentes técnicas.", "Gestión de crisis y comunicación.", "Redacción de informes claros."], "herramientas": ["Buscadores y fuentes públicas.", "Herramientas de líneas de tiempo y diagramas.", "Hoja de cálculo para ordenar los hechos.", "Editor de documentos o presentaciones."], "lineamientos": ["Utiliza solo información pública y cita siempre las fuentes de las que obtuviste cada dato. No intentes probar la fragilidad de ningún servicio real ni generar interrupciones para comprobar cómo reaccionan.", "Evita atribuir culpas a personas concretas o especular sobre causas que los informes no confirman: separa claramente lo que está documentado de lo que es tu interpretación."], "otroSector": "La misma metodología puede aplicarse a accidentes industriales, fallas en servicios públicos, errores en procesos hospitalarios, crisis de suministro o cualquier situación donde un fallo pequeño haya provocado consecuencias grandes."}$fcc6c24$::jsonb,7),
('de-una-tabla-desordenada-a-informacion-que-sirve','tecnologia',array['negocios']::text[],'De una tabla desordenada a información que sirve','Toma una tabla llena de errores y desorden, límpiala paso a paso y descubre qué información útil había escondida.','Análisis','~15 h',15,array['Datos','Limpieza de datos','Hoja de cálculo']::text[],array['investigar','resolver','otro-sector']::text[],'publicos','sin','ingenieria de sistemas ingenieria industrial estadistica administracion contabilidad economia computacion e informatica gestion de la informacion limpieza y preparacion de datos. formulas de hoja de calculo. analisis descriptivo. documentacion de decisiones. comunicacion de resultados. hoja de calculo. herramientas de limpieza de datos, como las de importacion y filtrado. documento para el informe.',$f7d5655${"id": "de-una-tabla-desordenada-a-informacion-que-sirve", "area": "tecnologia", "areas2": ["negocios"], "titulo": "De una tabla desordenada a información que sirve", "resumen": "Toma una tabla llena de errores y desorden, límpiala paso a paso y descubre qué información útil había escondida.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Datos", "Limpieza de datos", "Hoja de cálculo"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "publicos", "datosTexto": "públicos o ficticios: usa una tabla abierta de un portal de datos o crea una tabla con errores a propósito.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Estadística", "Administración", "Contabilidad", "Economía", "Computación e Informática", "Gestión de la Información"], "problema": ["Muchas organizaciones guardan sus datos en tablas con celdas vacías, nombres escritos de varias formas, fechas en formatos distintos y filas repetidas. Antes de poder analizar nada hay que arreglarlas, y ese trabajo casi nunca se enseña.", "Cuando se saltan este paso, los resultados parecen buenos pero están equivocados: un total mal sumado o un cliente contado dos veces cambian la decisión."], "desarrollar": ["Consigue una tabla real de datos abiertos o arma una con 200 a 500 filas con errores inventados. Haz un listado de los problemas que encuentras y corrígelos uno por uno, anotando qué cambió y por qué.", "Después responde tres preguntas de interés con la tabla ya limpia y compara con lo que habrías respondido sin limpiarla. El resultado puede ser un informe breve con un antes y un después."], "ampliaciones": [{"titulo": "Reglas reutilizables", "aporta": "convierte tus pasos de limpieza en una lista de reglas que sirva para la próxima tabla desordenada."}, {"titulo": "Un informe de calidad", "aporta": "agrega un resumen que cuente cuántos errores de cada tipo se encontraron."}, {"titulo": "Automatizar la limpieza", "aporta": "repite los pasos con una fórmula, una macro o un pequeño programa."}], "objetivos": ["Detectar y clasificar los problemas de una tabla.", "Aplicar correcciones documentando cada decisión.", "Comparar resultados antes y después de la limpieza.", "Redactar reglas de limpieza reutilizables.", "Presentar hallazgos sin tecnicismos."], "habilidades": ["Limpieza y preparación de datos.", "Fórmulas de hoja de cálculo.", "Análisis descriptivo.", "Documentación de decisiones.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Herramientas de limpieza de datos, como las de importación y filtrado.", "Documento para el informe."], "lineamientos": ["No modifiques el archivo original: trabaja siempre sobre una copia y deja registro de cada cambio.", "Si usas una tabla pública, cita la fuente y respeta su licencia de uso."], "otroSector": "El mismo procedimiento sirve para ordenar un padrón de clientes, una lista de inventario, un registro de asistencia o una base de datos de encuestas."}$f7d5655$::jsonb,8),
('si-una-pieza-falla-que-mas-se-cae','tecnologia',array['industria','ciudades']::text[],'Si una pieza falla, ¿qué más se cae?','Dibuja las dependencias entre las piezas de un sistema y descubre qué otras piezas dejan de funcionar cuando una falla.','Análisis','~15 h',15,array['Sistemas complejos','Dependencias','Gestión de riesgos']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas ingenieria de software ingenieria industrial ingenieria civil administracion computacion e informatica logistica pensamiento sistemico. diagramacion de procesos. gestion de riesgos. analisis de causas. comunicacion visual. herramienta de diagramas. hoja de calculo. documento para el informe.',$f852111${"id": "si-una-pieza-falla-que-mas-se-cae", "area": "tecnologia", "areas2": ["industria", "ciudades"], "titulo": "Si una pieza falla, ¿qué más se cae?", "resumen": "Dibuja las dependencias entre las piezas de un sistema y descubre qué otras piezas dejan de funcionar cuando una falla.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Sistemas complejos", "Dependencias", "Gestión de riesgos"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o públicos: dibuja las dependencias de un sistema inventado o de uno cuya arquitectura se haya publicado.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Ingeniería Civil", "Administración", "Computación e Informática", "Logística"], "problema": ["En un sistema complejo, una pieza pequeña puede sostener a muchas otras: un servicio de autenticación, una base de datos o un proveedor de energía. Cuando falla, el efecto se propaga de formas que nadie había previsto.", "Sin un mapa de dependencias, las organizaciones descubren qué dependía de qué en pleno incidente, cuando ya no hay tiempo de reaccionar."], "desarrollar": ["Elige un sistema conocido, como el de una tienda en línea o el de una institución educativa, y lista sus piezas principales. Dibuja un mapa donde cada flecha indica «necesita a» y marca qué piezas tienen muchas flechas llegando.", "Simula la caída de cada pieza una por una y anota cuántas otras quedan afectadas. El resultado puede ser un mapa con las piezas críticas resaltadas y una tabla que muestre el alcance de cada falla."], "ampliaciones": [{"titulo": "Planes de respaldo", "aporta": "agrega una alternativa a cada pieza crítica y estudia cuánto se reduce el daño."}, {"titulo": "Un caso real", "aporta": "compara tu mapa con el informe público de una caída famosa y mira qué dependencias no habías visto."}, {"titulo": "Un cálculo de riesgo", "aporta": "combina la probabilidad de que cada pieza falle con el alcance de su caída para ordenarlas por riesgo."}], "objetivos": ["Identificar las piezas de un sistema y sus relaciones.", "Representar las dependencias en un mapa claro.", "Reconocer las piezas críticas.", "Simular la caída de piezas y medir su alcance.", "Proponer medidas para reducir el riesgo."], "habilidades": ["Pensamiento sistémico.", "Diagramación de procesos.", "Gestión de riesgos.", "Análisis de causas.", "Comunicación visual."], "herramientas": ["Herramienta de diagramas.", "Hoja de cálculo.", "Documento para el informe."], "lineamientos": ["Usa sistemas inventados o públicos: no publiques detalles internos de una organización sin permiso.", "Aclara que tu mapa es una simplificación y que los sistemas reales tienen más piezas."], "otroSector": "El mismo mapa sirve para estudiar qué se detiene si falla un proveedor, una máquina, una ruta de transporte o una persona clave en una cadena de producción."}$f852111$::jsonb,9),
('documentos-repetidos-como-encontrarlos-y-con-cual-quedarte','tecnologia',array['negocios']::text[],'Documentos repetidos: cómo encontrarlos y con cuál quedarte','Diseña un procedimiento para encontrar documentos repetidos o casi iguales y decidir cuál conservar.','Prototipo','~15 h',15,array['Organización','Datos','Duplicados']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software computacion e informatica administracion contabilidad gestion de la informacion bibliotecologia secretariado organizacion de la informacion. comparacion de archivos. uso de hoja de calculo. criterios de decision. documentacion de procesos. explorador de archivos. hoja de calculo. opcionalmente un lenguaje de programacion para comparar archivos.',$f00a467${"id": "documentos-repetidos-como-encontrarlos-y-con-cual-quedarte", "area": "tecnologia", "areas2": ["negocios"], "titulo": "Documentos repetidos: cómo encontrarlos y con cuál quedarte", "resumen": "Diseña un procedimiento para encontrar documentos repetidos o casi iguales y decidir cuál conservar.", "tipo": "Prototipo", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Organización", "Datos", "Duplicados"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: crea una carpeta con archivos repetidos inventados, o usa una carpeta tuya sin información sensible.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Administración", "Contabilidad", "Gestión de la Información", "Bibliotecología", "Secretariado"], "problema": ["Con el tiempo, cualquier carpeta compartida acumula documentos repetidos con nombres distintos: «informe_final», «informe_final_2», «informe_final_definitivo». Nadie sabe cuál es el vigente y se pierde tiempo comparando.", "Eliminar sin cuidado puede borrar la versión buena, y no eliminar llena de confusión la carpeta."], "desarrollar": ["Prepara una carpeta de prueba con 50 a 100 archivos que incluya copias exactas, copias con pequeños cambios y archivos distintos con el mismo nombre. Diseña reglas para detectarlos: el tamaño, la fecha, el contenido y la huella digital del archivo.", "Aplica las reglas y revisa cuántos duplicados encuentras y cuántos casos son dudosos. Propón una política para decidir con cuál quedarse. El resultado puede ser un procedimiento paso a paso con ejemplos."], "ampliaciones": [{"titulo": "Casi iguales", "aporta": "detecta documentos que son muy parecidos aunque no idénticos y explica cómo medir su parecido."}, {"titulo": "Una carpeta real", "aporta": "aplica el método a una carpeta de trabajo compartida, con permiso, y mide cuánto espacio se libera."}, {"titulo": "Que se haga solo", "aporta": "automatiza la detección con una hoja o un pequeño programa."}], "objetivos": ["Reconocer los tipos de duplicados en una carpeta.", "Definir reglas para detectarlos.", "Probar las reglas y medir su acierto.", "Diseñar una política para decidir qué conservar.", "Documentar el procedimiento con ejemplos."], "habilidades": ["Organización de la información.", "Comparación de archivos.", "Uso de hoja de cálculo.", "Criterios de decisión.", "Documentación de procesos."], "herramientas": ["Explorador de archivos.", "Hoja de cálculo.", "Opcionalmente un lenguaje de programación para comparar archivos."], "lineamientos": ["Cuidados: haz siempre una copia de respaldo antes de eliminar y trabaja primero en una carpeta de prueba.", "No uses carpetas con información de otras personas sin su permiso."], "otroSector": "El mismo método sirve para depurar listas de clientes, padrones, catálogos de productos o bibliotecas de fotos y videos."}$f00a467$::jsonb,10),
('quien-puede-ver-que-roles-y-permisos-en-una-organizacion','tecnologia',array['derecho']::text[],'¿Quién puede ver qué? Roles y permisos en una organización','Diseña quién debe poder ver, editar o aprobar cada tipo de información en una organización, y comprueba que las reglas no dejen huecos.','Plan','~15 h',15,array['Seguridad digital','Control de acceso','Organización']::text[],array['resolver','crear','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas ingenieria de software ciberseguridad derecho administracion contabilidad auditoria computacion e informatica seguridad de la informacion. gestion de accesos. analisis de procesos. pensamiento preventivo. redaccion de politicas. hoja de calculo. herramienta de diagramas. documento para la politica.',$f0f8764${"id": "quien-puede-ver-que-roles-y-permisos-en-una-organizacion", "area": "tecnologia", "areas2": ["derecho"], "titulo": "¿Quién puede ver qué? Roles y permisos en una organización", "resumen": "Diseña quién debe poder ver, editar o aprobar cada tipo de información en una organización, y comprueba que las reglas no dejen huecos.", "tipo": "Plan", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Seguridad digital", "Control de acceso", "Organización"], "intencion": ["resolver", "crear", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: diseña los permisos de una organización inventada con sus áreas y cargos.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ciberseguridad", "Derecho", "Administración", "Contabilidad", "Auditoría", "Computación e Informática"], "problema": ["En muchas organizaciones los permisos se dan «por si acaso»: todos ven todo, o alguien con acceso total se va y nadie le quita lo que tenía. Más tarde aparecen fugas de información, errores por ediciones indebidas y personas que no pueden hacer su trabajo.", "El principio de dar a cada persona solo lo que necesita suena fácil, pero aplicarlo exige pensar quién hace qué y qué pasa cuando alguien cambia de cargo."], "desarrollar": ["Elige una organización inventada de unas 15 personas con tres o cuatro áreas y define los tipos de información que maneja: de clientes, financiera, de personal y pública. Arma una matriz que cruce cargos y tipos de información e indique si cada cargo puede ver, editar o aprobar.", "Prueba tu matriz con escenarios: alguien nuevo, alguien que cambia de área, alguien que se va. Busca huecos y excesos. El resultado puede ser una matriz y una lista de reglas para mantenerla."], "ampliaciones": [{"titulo": "Casos especiales", "aporta": "agrega excepciones temporales, como un auditor que revisa por una semana."}, {"titulo": "Revisión periódica", "aporta": "diseña una rutina trimestral para detectar permisos que ya no corresponden."}, {"titulo": "Una versión ejecutable", "aporta": "convierte la matriz en un pequeño sistema que responda si alguien tiene permiso."}], "objetivos": ["Clasificar la información según su sensibilidad.", "Definir cargos y sus necesidades de acceso.", "Construir una matriz de permisos coherente.", "Probarla con escenarios de cambio.", "Redactar reglas de mantenimiento."], "habilidades": ["Seguridad de la información.", "Gestión de accesos.", "Análisis de procesos.", "Pensamiento preventivo.", "Redacción de políticas."], "herramientas": ["Hoja de cálculo.", "Herramienta de diagramas.", "Documento para la política."], "lineamientos": ["Cuidados: diseña con una organización inventada. No pidas ni uses la lista real de permisos de ninguna institución.", "Explica las reglas de forma clara: una política que nadie entiende no se cumple."], "otroSector": "La misma matriz sirve para una asociación de vecinos, una iglesia, un club o cualquier grupo que comparta archivos, llaves o cuentas."}$f0f8764$::jsonb,11),
('que-tan-facil-es-enganar-a-un-sistema-con-datos-falsos','tecnologia',array['sociedad']::text[],'¿Qué tan fácil es engañar a un sistema con datos falsos?','Prueba qué pasa cuando un formulario o un sistema recibe datos falsos, absurdos o malintencionados, y diseña reglas para detectarlos.','Análisis','~15 h',15,array['Validación de datos','Seguridad digital','Calidad']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ciberseguridad computacion e informatica auditoria estadistica administracion validacion de datos. pruebas de software. seguridad basica. diseno de formularios. pensamiento critico. un formulario de practica o una hoja con validacion. hoja de calculo para registrar los casos. opcionalmente un lenguaje web.',$fd79545${"id": "que-tan-facil-es-enganar-a-un-sistema-con-datos-falsos", "area": "tecnologia", "areas2": ["sociedad"], "titulo": "¿Qué tan fácil es engañar a un sistema con datos falsos?", "resumen": "Prueba qué pasa cuando un formulario o un sistema recibe datos falsos, absurdos o malintencionados, y diseña reglas para detectarlos.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Validación de datos", "Seguridad digital", "Calidad"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: usa un formulario de práctica que tú mismo crees o un modelo de ejemplo, nunca un sistema real de otra persona.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ciberseguridad", "Computación e Informática", "Auditoría", "Estadística", "Administración"], "problema": ["Casi todos los sistemas confían en lo que reciben: una edad, un monto, un correo. Pero hay quien escribe datos absurdos por error, por broma o a propósito: una fecha de nacimiento en el año 3000, un precio negativo, un texto larguísimo.", "Cuando el sistema no valida, esos datos llegan a la base de datos, descuadran reportes y a veces abren una puerta a ataques."], "desarrollar": ["Diseña un formulario de práctica con seis o siete campos y haz una lista de los datos extraños que podrían ingresarse en cada uno. Pruébalos uno por uno y anota qué hace el sistema: los acepta, los rechaza o falla.", "Define reglas de validación para cada campo y vuelve a probar. El resultado puede ser una tabla de casos con lo que pasaba antes y después de las reglas, y una guía de validaciones que cualquiera pueda aplicar."], "ampliaciones": [{"titulo": "Validar en dos lugares", "aporta": "explica por qué no basta validar en la pantalla y qué más se debe revisar."}, {"titulo": "Datos que parecen buenos", "aporta": "estudia casos donde el dato es válido pero falso, y qué se puede hacer."}, {"titulo": "Un catálogo de casos raros", "aporta": "arma una lista reutilizable de entradas extrañas para probar cualquier formulario."}], "objetivos": ["Identificar entradas extrañas posibles en cada campo.", "Probar el comportamiento del sistema.", "Definir reglas de validación claras.", "Verificar que las reglas funcionen.", "Documentar una guía reutilizable."], "habilidades": ["Validación de datos.", "Pruebas de software.", "Seguridad básica.", "Diseño de formularios.", "Pensamiento crítico."], "herramientas": ["Un formulario de práctica o una hoja con validación.", "Hoja de cálculo para registrar los casos.", "Opcionalmente un lenguaje web."], "lineamientos": ["Cuidados: prueba solo sistemas que tú construyas o que sean de práctica. Introducir datos manipulados en un sistema ajeno puede causar daños y tener consecuencias legales.", "Enfócate en proteger y no en atacar: el objetivo es que el sistema rechace lo que no corresponde."], "otroSector": "El mismo análisis sirve para revisar formularios de matrícula, de pedidos, de encuestas, de registro de asistencia o de solicitudes de un trámite."}$fd79545$::jsonb,12),
('cuanto-tardara-de-verdad-un-proyecto-de-software','tecnologia',array['negocios']::text[],'¿Cuánto tardará de verdad un proyecto de software?','Aprende a estimar cuánto tardará un proyecto y a revisar tus estimaciones comparándolas con lo que realmente ocurrió.','Análisis','~15 h',15,array['Estimación','Gestión de proyectos','Software']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas ingenieria de software ingenieria industrial administracion computacion e informatica arquitectura gestion de proyectos gestion de proyectos. estimacion de tiempos. analisis de datos propios. autoevaluacion. planificacion. hoja de calculo. herramienta de gestion de tareas. documento para la plantilla.',$f05fa4a${"id": "cuanto-tardara-de-verdad-un-proyecto-de-software", "area": "tecnologia", "areas2": ["negocios"], "titulo": "¿Cuánto tardará de verdad un proyecto de software?", "resumen": "Aprende a estimar cuánto tardará un proyecto y a revisar tus estimaciones comparándolas con lo que realmente ocurrió.", "tipo": "Análisis", "tiempo": "~15 h", "horas": 15, "etiquetas": ["Estimación", "Gestión de proyectos", "Software"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o propios: usa el historial de tus propios trabajos o los de un proyecto inventado.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Administración", "Computación e Informática", "Arquitectura", "Gestión de Proyectos"], "problema": ["Casi todos los proyectos tardan más de lo que se dijo al inicio. El error no suele ser mala fe, sino olvidar las tareas ocultas, las esperas, los cambios de último momento y el tiempo de probar y corregir.", "Una estimación poco realista termina en entregas apuradas, equipos agotados y clientes molestos, y pocas personas se entrenan en hacerla mejor."], "desarrollar": ["Reúne el historial de cinco trabajos tuyos, escolares o personales, con el tiempo que estimaste y el que realmente tomó. Calcula en cuánto te equivocaste en cada uno y busca un patrón: ¿siempre subestimas?, ¿qué tipo de tarea se te pasa?", "Con eso diseña un método personal de estimación, con un margen de seguridad y una lista de tareas olvidadas, y úsalo en un proyecto nuevo. El resultado puede ser una plantilla de estimación y un informe de lo aprendido."], "ampliaciones": [{"titulo": "Estimar en equipo", "aporta": "compara tu estimación con la de dos compañeros y analiza por qué difieren."}, {"titulo": "Rangos, no un número", "aporta": "expresa cada estimación como un rango y mide cuántas veces el resultado cae dentro."}, {"titulo": "Con datos de otros", "aporta": "busca información pública sobre retrasos de proyectos y compara con tu experiencia."}], "objetivos": ["Registrar estimaciones y tiempos reales.", "Calcular el error de estimación.", "Identificar patrones de subestimación.", "Diseñar un método personal de estimación.", "Aplicarlo a un proyecto nuevo y evaluarlo."], "habilidades": ["Gestión de proyectos.", "Estimación de tiempos.", "Análisis de datos propios.", "Autoevaluación.", "Planificación."], "herramientas": ["Hoja de cálculo.", "Herramienta de gestión de tareas.", "Documento para la plantilla."], "lineamientos": ["Usa tus propios datos o datos inventados y evita publicar información de proyectos de otras personas.", "Una estimación es un rango razonado, no una promesa: acláralo cuando la presentes."], "otroSector": "La misma práctica sirve para estimar una obra de construcción, un evento, una mudanza, la preparación de una tesis o el lanzamiento de un producto."}$f05fa4a$::jsonb,13),
('como-se-ve-una-actividad-inusual-en-un-registro','tecnologia',array['ciencias']::text[],'¿Cómo se ve una actividad inusual en un registro?','Aprende a leer un registro de actividad y a reconocer comportamientos que se salen de lo normal.','Análisis','~20 h',20,array['Seguridad digital','Anomalías','Análisis de registros']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ciberseguridad estadistica contabilidad ingenieria industrial computacion e informatica auditoria analisis exploratorio de datos. estadistica descriptiva. seguridad de la informacion. lectura de registros tecnicos. comunicacion de hallazgos. hoja de calculo con filtros y tablas dinamicas. lenguaje de programacion para analisis de datos, opcional. herramienta de graficos.',$f51723c${"id": "como-se-ve-una-actividad-inusual-en-un-registro", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "¿Cómo se ve una actividad inusual en un registro?", "resumen": "Aprende a leer un registro de actividad y a reconocer comportamientos que se salen de lo normal.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Seguridad digital", "Anomalías", "Análisis de registros"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: genera un registro de actividad inventado con algunas anomalías colocadas a propósito, o usa uno público de práctica.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ciberseguridad", "Estadística", "Contabilidad", "Ingeniería Industrial", "Computación e Informática", "Auditoría"], "problema": ["Los sistemas dejan un registro de todo lo que ocurre: inicios de sesión, descargas, errores y cambios. Casi nadie lo revisa porque son miles de líneas, y las señales de un problema quedan enterradas entre actividad normal.", "Detectar lo raro exige saber primero qué es lo normal, y ese punto de partida casi nunca se establece."], "desarrollar": ["Prepara un registro ficticio de una semana de actividad con 1000 a 5000 líneas, que incluya patrones normales y cinco o seis anomalías: muchos intentos fallidos seguidos, un acceso en horario extraño, una descarga inusualmente grande. Resume cómo es un día normal con promedios y gráficos.", "Luego busca las anomalías sin saber dónde están y anota qué señales te hicieron sospechar. El resultado puede ser un informe breve con las pistas que funcionaron y las que dieron falsas alarmas."], "ampliaciones": [{"titulo": "Un umbral inteligente", "aporta": "compara una regla fija, como «más de cinco fallos», con una que se adapte a cada usuario."}, {"titulo": "Falsas alarmas", "aporta": "cuenta cuántas veces una regla alarma sin motivo y qué costo tendría en una organización real."}, {"titulo": "Un detector automático", "aporta": "convierte tus reglas en un programa que revise el registro y marque lo sospechoso."}], "objetivos": ["Describir el comportamiento normal a partir de un registro.", "Identificar anomalías y clasificarlas por tipo.", "Definir señales y umbrales de aviso.", "Medir falsas alarmas y casos no detectados.", "Comunicar los hallazgos con claridad."], "habilidades": ["Análisis exploratorio de datos.", "Estadística descriptiva.", "Seguridad de la información.", "Lectura de registros técnicos.", "Comunicación de hallazgos."], "herramientas": ["Hoja de cálculo con filtros y tablas dinámicas.", "Lenguaje de programación para análisis de datos, opcional.", "Herramienta de gráficos."], "lineamientos": ["Cuidados: trabaja solo con registros ficticios o públicos. Los registros reales contienen datos de personas y requieren permiso.", "Recuerda que una actividad inusual no siempre es un ataque: puede ser una persona viajando o un cambio de rutina."], "otroSector": "El mismo método sirve para detectar movimientos raros en un registro de ventas, de gastos, de producción o de asistencia."}$f51723c$::jsonb,14),
('cuanto-tarda-realmente-una-aplicacion-en-responder','tecnologia','{}'::text[],'¿Cuánto tarda realmente una aplicación en responder?','Mide cuánto demora una aplicación en responder, descubre de qué depende y cuándo la espera se vuelve molesta.','Investigación','~20 h',20,array['Rendimiento','Mediciones','Experiencia de usuario']::text[],array['investigar']::text[],'propios','opcional','ingenieria de sistemas ingenieria de software telecomunicaciones estadistica computacion e informatica diseno web administracion medicion y registro de datos. estadistica descriptiva. herramientas de desarrollo del navegador. analisis de resultados. redaccion tecnica. herramientas de desarrollo del navegador. hoja de calculo. opcionalmente un lenguaje de programacion para automatizar las mediciones.',$f24bdb5${"id": "cuanto-tarda-realmente-una-aplicacion-en-responder", "area": "tecnologia", "areas2": [], "titulo": "¿Cuánto tarda realmente una aplicación en responder?", "resumen": "Mide cuánto demora una aplicación en responder, descubre de qué depende y cuándo la espera se vuelve molesta.", "tipo": "Investigación", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Rendimiento", "Mediciones", "Experiencia de usuario"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "propios: mide páginas o aplicaciones de uso libre desde tu propia conexión, con pocas pruebas y sin sobrecargarlas.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Telecomunicaciones", "Estadística", "Computación e Informática", "Diseño Web", "Administración"], "problema": ["Todos sabemos cuando una aplicación «va lenta», pero casi nunca sabemos cuánto tarda en números ni de qué depende: de nuestra conexión, de la hora, del tamaño de lo que pedimos o del servidor.", "Sin medir, las quejas se quedan en «va lento» y los equipos no saben dónde mejorar. Además, la percepción de la espera cambia mucho según lo que la persona esté haciendo."], "desarrollar": ["Elige tres aplicaciones o páginas de uso libre y una tarea concreta en cada una, como abrir una página o buscar un dato. Mide el tiempo de respuesta al menos veinte veces, en distintos momentos del día, y registra los resultados.", "Calcula el promedio, el mínimo, el máximo y cuántas veces se superó un umbral de cinco segundos. El resultado puede ser un informe con gráficos que muestre en qué casos y por qué la espera se vuelve insoportable."], "ampliaciones": [{"titulo": "Qué hace lento a un servicio", "aporta": "usa las herramientas del navegador para ver qué parte de la carga tarda más."}, {"titulo": "Con distintas conexiones", "aporta": "repite las mediciones con datos móviles y con una red de casa, y compara."}, {"titulo": "El umbral de paciencia", "aporta": "pregunta a diez personas cuánto esperarían antes de abandonar una tarea y compáralo con tus tiempos medidos."}], "objetivos": ["Diseñar un procedimiento de medición repetible.", "Registrar tiempos en distintos momentos y condiciones.", "Calcular indicadores básicos de tiempo de respuesta.", "Relacionar los resultados con factores posibles.", "Presentar las conclusiones con gráficos claros."], "habilidades": ["Medición y registro de datos.", "Estadística descriptiva.", "Herramientas de desarrollo del navegador.", "Análisis de resultados.", "Redacción técnica."], "herramientas": ["Herramientas de desarrollo del navegador.", "Hoja de cálculo.", "Opcionalmente un lenguaje de programación para automatizar las mediciones."], "lineamientos": ["Cuidados: mide con pocas solicitudes y espaciadas. No sobrecargues servicios ajenos ni hagas pruebas masivas sin autorización.", "Indica siempre cuándo y desde dónde mediste: los resultados cambian con la hora y la conexión."], "otroSector": "La misma pregunta sirve para medir la espera en una ventanilla, la entrega de un pedido, el tiempo de respuesta de una línea de atención o el despacho de una farmacia."}$f24bdb5$::jsonb,15),
('que-tan-buenos-son-los-datos-de-una-organizacion','tecnologia',array['negocios']::text[],'¿Qué tan buenos son los datos de una organización?','Aprende a medir la calidad de una base de datos y a decidir qué corregir primero.','Análisis','~20 h',20,array['Calidad de datos','Datos','Gestión de la información']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas estadistica administracion contabilidad ingenieria industrial gestion de la informacion computacion e informatica auditoria calidad de datos. uso de hoja de calculo. estadistica descriptiva. gestion de la informacion. redaccion de informes. hoja de calculo. herramientas de filtros y tablas dinamicas. documento para el informe.',$f25c29d${"id": "que-tan-buenos-son-los-datos-de-una-organizacion", "area": "tecnologia", "areas2": ["negocios"], "titulo": "¿Qué tan buenos son los datos de una organización?", "resumen": "Aprende a medir la calidad de una base de datos y a decidir qué corregir primero.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Calidad de datos", "Datos", "Gestión de la información"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios o públicos: trabaja con una base inventada de clientes o productos, o con una tabla abierta de una institución pública.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Estadística", "Administración", "Contabilidad", "Ingeniería Industrial", "Gestión de la Información", "Computación e Informática", "Auditoría"], "problema": ["Las organizaciones toman decisiones con sus datos, pero rara vez saben qué tan confiables son: cuántos están incompletos, cuántos están repetidos, cuántos se contradicen o cuántos están desactualizados.", "Mientras no se mide, la calidad se discute con opiniones. Con medidas simples se puede decidir dónde conviene invertir tiempo."], "desarrollar": ["Elige una tabla de 500 a 2000 filas y define cuatro criterios de calidad: completitud, unicidad, consistencia y actualidad. Calcula para cada criterio un porcentaje y busca ejemplos concretos de errores.", "Ordena los problemas por el daño que causarían en una decisión real y propone qué corregir primero. El resultado puede ser un informe de calidad con una semaforización por columna."], "ampliaciones": [{"titulo": "Un puntaje", "aporta": "combina los cuatro criterios en un solo indicador y analiza si es justo para comparar tablas distintas."}, {"titulo": "Errores nuevos", "aporta": "revisa cómo se podrían evitar desde el origen, por ejemplo, validando los campos al ingresar."}, {"titulo": "Con inteligencia artificial", "aporta": "mira cómo afectan estos problemas a un modelo y conecta con la idea de qué le pasa a una IA cuando los datos no son perfectos."}], "objetivos": ["Definir criterios de calidad de datos.", "Calcular indicadores por criterio y por columna.", "Encontrar y ejemplificar errores concretos.", "Priorizar las correcciones por su impacto.", "Presentar un informe claro a una persona no técnica."], "habilidades": ["Calidad de datos.", "Uso de hoja de cálculo.", "Estadística descriptiva.", "Gestión de la información.", "Redacción de informes."], "herramientas": ["Hoja de cálculo.", "Herramientas de filtros y tablas dinámicas.", "Documento para el informe."], "lineamientos": ["No uses datos reales de personas: trabaja con una base inventada o con una tabla pública.", "Indica los criterios y los porcentajes de forma transparente para que otra persona pueda repetir el cálculo."], "otroSector": "El mismo método sirve para revisar una lista de alumnos, un inventario, un padrón de socios, una agenda de contactos o los registros de una clínica pequeña."}$f25c29d$::jsonb,16),
('el-recorrido-de-un-dato-de-donde-viene-y-quien-lo-toco','tecnologia',array['derecho']::text[],'El recorrido de un dato: ¿de dónde viene y quién lo tocó?','Sigue un dato desde que se crea hasta que aparece en un informe, y comprueba si se puede reconstruir qué cambios sufrió y quién los hizo.','Análisis','~20 h',20,array['Trazabilidad','Datos','Auditoría']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','ingenieria de sistemas contabilidad auditoria derecho administracion gestion de la informacion computacion e informatica ciencia de datos gestion de datos. diagramacion de procesos. auditoria de la informacion. analisis de causas. documentacion. herramienta de diagramas. hoja de calculo. documento para el informe.',$f80cce1${"id": "el-recorrido-de-un-dato-de-donde-viene-y-quien-lo-toco", "area": "tecnologia", "areas2": ["derecho"], "titulo": "El recorrido de un dato: ¿de dónde viene y quién lo tocó?", "resumen": "Sigue un dato desde que se crea hasta que aparece en un informe, y comprueba si se puede reconstruir qué cambios sufrió y quién los hizo.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Trazabilidad", "Datos", "Auditoría"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: crea un conjunto de datos inventado que pase por varias manos, como una venta que se registra, se corrige y se reporta.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Contabilidad", "Auditoría", "Derecho", "Administración", "Gestión de la Información", "Computación e Informática", "Ciencia de Datos"], "problema": ["Una cifra que aparece en un informe puede venir de varias personas y de varias correcciones. Cuando alguien pregunta «¿de dónde salió este número?», a menudo nadie sabe responder con certeza.", "Sin ese rastro no se pueden corregir errores a tiempo ni demostrar que una información es confiable."], "desarrollar": ["Elige un dato importante en un proceso inventado, como el total de ventas del mes, y reconstruye su recorrido: dónde se ingresó, quién lo modificó, qué transformaciones sufrió y cómo llegó al informe. Registra cada paso con fecha y responsable.", "Después simula un error en el origen y observa qué pasos del recorrido permiten encontrarlo y qué huecos lo dificultan. El resultado puede ser un diagrama del recorrido y una lista de lo que debería registrarse siempre."], "ampliaciones": [{"titulo": "Un rastro automático", "aporta": "diseña un registro de cambios que anote quién modificó qué y cuándo."}, {"titulo": "Quitar el misterio", "aporta": "explica el recorrido a una persona sin formación técnica y comprueba si lo entiende."}, {"titulo": "Comparar procesos", "aporta": "aplica la idea a dos procesos distintos y analiza cuál deja más rastro."}], "objetivos": ["Mapear el recorrido de un dato.", "Registrar cada transformación y su responsable.", "Identificar huecos en el rastro.", "Simular un error y buscar su origen.", "Definir qué información debe registrarse siempre."], "habilidades": ["Gestión de datos.", "Diagramación de procesos.", "Auditoría de la información.", "Análisis de causas.", "Documentación."], "herramientas": ["Herramienta de diagramas.", "Hoja de cálculo.", "Documento para el informe."], "lineamientos": ["Trabaja con datos ficticios y con procesos inventados.", "Si el caso incluye personas, usa nombres inventados."], "otroSector": "La misma idea sirve para seguir un expediente, una donación, una receta médica, un lote de producción o el origen de una noticia."}$f80cce1$::jsonb,17),
('como-se-guarda-la-informacion-de-algo-cotidiano','tecnologia',array['negocios']::text[],'¿Cómo se guarda la información de algo cotidiano?','Elige algo cotidiano, como una biblioteca o una bodega, y diseña cómo guardar su información de forma ordenada, sin repeticiones ni contradicciones.','Prototipo','~20 h',20,array['Bases de datos','Modelado','Diseño']::text[],array['crear','resolver','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software computacion e informatica administracion contabilidad bibliotecologia ingenieria industrial modelado de datos. diseno de bases de datos. analisis de requisitos. consultas basicas. documentacion tecnica. herramienta de diagramas. hoja de calculo o gestor de bases de datos gratuito. documento para explicar el diseno.',$fb73973${"id": "como-se-guarda-la-informacion-de-algo-cotidiano", "area": "tecnologia", "areas2": ["negocios"], "titulo": "¿Cómo se guarda la información de algo cotidiano?", "resumen": "Elige algo cotidiano, como una biblioteca o una bodega, y diseña cómo guardar su información de forma ordenada, sin repeticiones ni contradicciones.", "tipo": "Prototipo", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Bases de datos", "Modelado", "Diseño"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: inventa los datos de una biblioteca, una bodega o un club.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Administración", "Contabilidad", "Bibliotecología", "Ingeniería Industrial"], "problema": ["Casi todo negocio empieza con una hoja de cálculo donde todo está junto: clientes, productos, ventas. Con el tiempo aparecen datos repetidos, nombres escritos de varias formas y cambios que obligan a modificar muchas filas.", "Pensar antes cómo se organiza la información evita esos problemas y hace que cualquier sistema posterior sea más sencillo, pero casi nadie lo aprende hasta que el desorden ya es grande."], "desarrollar": ["Elige un caso y haz una lista de lo que hay que recordar: personas, objetos, acciones y sus relaciones. Dibuja un diagrama sencillo que muestre las cosas importantes y cómo se conectan, y luego convierte el diagrama en tablas con sus columnas.", "Carga 20 a 30 datos ficticios y prueba si puedes responder preguntas típicas sin repetir información. El resultado puede ser un diagrama, el diseño de las tablas y un ejemplo con datos."], "ampliaciones": [{"titulo": "Preguntas de verdad", "aporta": "escribe diez preguntas que el negocio quisiera responder y comprueba si tu diseño las permite."}, {"titulo": "Cambios en el tiempo", "aporta": "agrega historial: qué pasa si un cliente cambia de dirección o un producto cambia de precio."}, {"titulo": "Una versión navegable", "aporta": "construye una pantalla sencilla para consultar y registrar datos."}], "objetivos": ["Identificar las entidades y relaciones de un caso.", "Dibujar un diagrama claro del modelo.", "Convertirlo en tablas sin repeticiones.", "Probarlo con datos y preguntas típicas.", "Explicar las decisiones de diseño."], "habilidades": ["Modelado de datos.", "Diseño de bases de datos.", "Análisis de requisitos.", "Consultas básicas.", "Documentación técnica."], "herramientas": ["Herramienta de diagramas.", "Hoja de cálculo o gestor de bases de datos gratuito.", "Documento para explicar el diseño."], "lineamientos": ["Empieza con pocas tablas y amplía solo cuando las primeras funcionen.", "Usa datos ficticios: no cargues información real de clientes o socios."], "otroSector": "El mismo proceso sirve para un consultorio, un colegio, un gimnasio, un taller, una feria o una asociación."}$fb73973$::jsonb,18),
('como-se-prueba-un-programa-antes-de-entregarlo','tecnologia','{}'::text[],'¿Cómo se prueba un programa antes de entregarlo?','Aprende a diseñar pruebas para un programa o una hoja de cálculo, de modo que los errores se encuentren antes de que los encuentre el cliente.','Guía','~20 h',20,array['Pruebas','Calidad de software','Buenas prácticas']::text[],array['resolver']::text[],'propios','opcional','ingenieria de software ingenieria de sistemas computacion e informatica analisis de sistemas ingenieria industrial contabilidad administracion pruebas de software. pensamiento critico. diseno de casos. documentacion de errores. comunicacion tecnica. hoja de calculo para el plan de pruebas. el programa o la hoja que se va a probar. opcionalmente, una herramienta de pruebas automaticas.',$fcd0559${"id": "como-se-prueba-un-programa-antes-de-entregarlo", "area": "tecnologia", "areas2": [], "titulo": "¿Cómo se prueba un programa antes de entregarlo?", "resumen": "Aprende a diseñar pruebas para un programa o una hoja de cálculo, de modo que los errores se encuentren antes de que los encuentre el cliente.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Pruebas", "Calidad de software", "Buenas prácticas"], "intencion": ["resolver"], "datos": "propios", "datosTexto": "propios o ficticios: puedes probar un programa pequeño tuyo, una hoja de cálculo con fórmulas o una aplicación de uso libre.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Software", "Ingeniería de Sistemas", "Computación e Informática", "Análisis de Sistemas", "Ingeniería Industrial", "Contabilidad", "Administración"], "problema": ["Muchos programas y hojas de cálculo se entregan después de probarlos con un solo ejemplo que funcionó. Los errores aparecen con valores raros, con datos vacíos o cuando se usa de una manera que el autor no imaginó.", "Probar bien es una habilidad que casi no se enseña, pero es una de las que más piden en el trabajo: encontrar errores antes de que cuesten dinero."], "desarrollar": ["Elige un programa pequeño o una hoja con fórmulas y escribe una lista de casos de prueba que incluya lo normal, los límites, los valores extraños y los errores del usuario. Ejecuta cada caso, anota el resultado esperado y el obtenido y registra los fallos.", "Clasifica los errores por gravedad y propón las correcciones. El resultado puede ser un plan de pruebas con una tabla de casos y un informe de los problemas encontrados."], "ampliaciones": [{"titulo": "Pruebas que se repiten", "aporta": "automatiza tus casos para que se ejecuten con un solo clic cada vez que cambies algo."}, {"titulo": "Probar como usuario", "aporta": "pide a tres personas que usen el programa sin instrucciones y registra qué errores provocan."}, {"titulo": "Cuánto se probó", "aporta": "mide qué partes del programa tocó tu plan de pruebas y cuáles quedaron sin revisar."}], "objetivos": ["Identificar los casos de prueba relevantes.", "Documentar resultado esperado y obtenido.", "Clasificar los errores por gravedad.", "Proponer correcciones.", "Comunicar los hallazgos con claridad."], "habilidades": ["Pruebas de software.", "Pensamiento crítico.", "Diseño de casos.", "Documentación de errores.", "Comunicación técnica."], "herramientas": ["Hoja de cálculo para el plan de pruebas.", "El programa o la hoja que se va a probar.", "Opcionalmente, una herramienta de pruebas automáticas."], "lineamientos": ["Prueba solo programas tuyos o de uso libre. No intentes romper sistemas ajenos.", "Reporta los errores de forma respetuosa y con pasos para repetirlos."], "otroSector": "Las mismas ideas sirven para probar formularios, procesos de una oficina, recetas, instructivos y cualquier procedimiento que otras personas vayan a seguir."}$fcd0559$::jsonb,19),
('como-se-documenta-un-sistema-para-que-otro-pueda-mantenerlo','tecnologia',array['educacion']::text[],'¿Cómo se documenta un sistema para que otro pueda mantenerlo?','Aprende a documentar un sistema de modo que otra persona lo entienda, lo use y lo arregle sin tener que llamar a quien lo hizo.','Guía','~20 h',20,array['Documentación','Trabajo en equipo','Mantenimiento']::text[],array['resolver','otro-sector']::text[],'propios','sin','ingenieria de sistemas ingenieria de software computacion e informatica administracion contabilidad ingenieria industrial educacion comunicaciones redaccion tecnica. diagramacion. empatia con el usuario. organizacion de la informacion. trabajo en equipo. editor de documentos. herramienta de diagramas. hoja de calculo o el sistema que se va a documentar.',$fbada4d${"id": "como-se-documenta-un-sistema-para-que-otro-pueda-mantenerlo", "area": "tecnologia", "areas2": ["educacion"], "titulo": "¿Cómo se documenta un sistema para que otro pueda mantenerlo?", "resumen": "Aprende a documentar un sistema de modo que otra persona lo entienda, lo use y lo arregle sin tener que llamar a quien lo hizo.", "tipo": "Guía", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Documentación", "Trabajo en equipo", "Mantenimiento"], "intencion": ["resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: documenta un trabajo tuyo, como una hoja de cálculo compleja o un programa pequeño, o un sistema inventado.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Computación e Informática", "Administración", "Contabilidad", "Ingeniería Industrial", "Educación", "Comunicaciones"], "problema": ["Cuando alguien se va de una organización, deja sistemas, hojas y procesos que solo él entendía. Quien llega no sabe qué hace cada parte ni por qué se hizo así, y tiene miedo de tocar algo y romperlo todo.", "La documentación suele dejarse para el final y por eso casi no se escribe. Escribirla bien, breve y útil, es una habilidad distinta de la de construir."], "desarrollar": ["Elige un sistema que hayas hecho y escribe cuatro cosas: para qué sirve, cómo se usa, cómo está organizado y qué hacer cuando algo falla. Incluye un diagrama sencillo de sus partes y una lista de las decisiones importantes y su razón.", "Pídele a una persona que no lo conozca que lo use y lo arregle siguiendo solo tu documentación, y registra dónde se atasca. El resultado puede ser un documento breve, un diagrama y una versión corregida después de la prueba."], "ampliaciones": [{"titulo": "Una versión de una página", "aporta": "condensa la documentación en una hoja que alguien pueda leer en cinco minutos."}, {"titulo": "Preguntas frecuentes", "aporta": "agrega una sección con las dudas que más surgieron en la prueba."}, {"titulo": "Mantenerla viva", "aporta": "define una regla para actualizar la documentación cada vez que cambie el sistema."}], "objetivos": ["Identificar qué necesita saber quien recibe un sistema.", "Redactar instrucciones claras de uso y de mantenimiento.", "Dibujar un diagrama de las partes.", "Probar la documentación con otra persona.", "Corregir los puntos donde se confundió."], "habilidades": ["Redacción técnica.", "Diagramación.", "Empatía con el usuario.", "Organización de la información.", "Trabajo en equipo."], "herramientas": ["Editor de documentos.", "Herramienta de diagramas.", "Hoja de cálculo o el sistema que se va a documentar."], "lineamientos": ["Cuidados: no incluyas contraseñas ni datos personales en la documentación: indica dónde se guardan, pero no los escribas.", "Escribe pensando en alguien con poca experiencia: si él entiende, cualquiera entiende."], "otroSector": "La misma práctica sirve para dejar instrucciones de una caja de ventas, un proceso contable, el manejo de una máquina o la rutina de un club."}$fbada4d$::jsonb,20),
('como-saber-si-un-cambio-realmente-funciono','tecnologia',array['negocios','ciencias']::text[],'¿Cómo saber si un cambio realmente funcionó?','Aprende a comparar dos versiones de algo, como una página, un mensaje o un proceso, y a decidir con números cuál es mejor.','Análisis','~20 h',20,array['Experimentación','Estadística','Decisiones']::text[],array['investigar','resolver','otro-sector']::text[],'ficticios','sin','estadistica ingenieria de sistemas administracion marketing economia psicologia ingenieria industrial ciencia de datos estadistica basica. diseno de experimentos. hoja de calculo. pensamiento critico. comunicacion de resultados. hoja de calculo. herramienta de graficos. calculadora estadistica.',$f6c41c7${"id": "como-saber-si-un-cambio-realmente-funciono", "area": "tecnologia", "areas2": ["negocios", "ciencias"], "titulo": "¿Cómo saber si un cambio realmente funcionó?", "resumen": "Aprende a comparar dos versiones de algo, como una página, un mensaje o un proceso, y a decidir con números cuál es mejor.", "tipo": "Análisis", "tiempo": "~20 h", "horas": 20, "etiquetas": ["Experimentación", "Estadística", "Decisiones"], "intencion": ["investigar", "resolver", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: simula los resultados de un experimento con números inventados que tú controlas.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Estadística", "Ingeniería de Sistemas", "Administración", "Marketing", "Economía", "Psicología", "Ingeniería Industrial", "Ciencia de Datos"], "problema": ["Una tienda cambia el color de un botón y las ventas suben. ¿Fue por el botón o por el día? Muchos cambios se celebran o se descartan por intuición, sin saber si la diferencia observada fue real o puro azar.", "Sin una forma clara de comparar, las organizaciones repiten decisiones equivocadas y dejan pasar las buenas."], "desarrollar": ["Plantea un caso, por ejemplo, dos versiones de un mensaje de recordatorio, y simula los resultados de mostrar cada versión a 200 personas: cuántas respondieron. Calcula la diferencia entre ambas y estima si es grande para ser casualidad.", "Repite la simulación varias veces con distintos tamaños de grupo y observa cuándo la conclusión es confiable y cuándo no. El resultado puede ser un informe con las reglas para decidir y los errores más comunes."], "ampliaciones": [{"titulo": "Muestras pequeñas", "aporta": "estudia cuántas personas hacen falta para confiar en una diferencia."}, {"titulo": "Mirar demasiado", "aporta": "muestra cómo detener la prueba apenas se ve una diferencia puede engañar."}, {"titulo": "Una prueba real", "aporta": "diseña y ejecuta una comparación con un grupo pequeño, con permiso, y analiza los resultados."}], "objetivos": ["Plantear una comparación entre dos versiones.", "Simular y registrar resultados.", "Calcular la diferencia y su variabilidad.", "Distinguir una diferencia real de una casualidad.", "Redactar reglas de decisión simples."], "habilidades": ["Estadística básica.", "Diseño de experimentos.", "Hoja de cálculo.", "Pensamiento crítico.", "Comunicación de resultados."], "herramientas": ["Hoja de cálculo.", "Herramienta de gráficos.", "Calculadora estadística."], "lineamientos": ["Si pruebas con personas reales, avísales y no recojas datos que las identifiquen.", "Evita concluir demasiado: una prueba con pocos casos no demuestra nada firme."], "otroSector": "El mismo método sirve para comparar dos recetas, dos horarios de atención, dos métodos de estudio o dos anuncios de una campaña."}$f6c41c7$::jsonb,21),
('cien-personas-en-la-misma-red-que-pasa-con-la-velocidad','tecnologia',array['ciencias']::text[],'Cien personas en la misma red: ¿qué pasa con la velocidad?','Simula qué ocurre con la velocidad de una conexión cuando cada vez más personas la comparten, y encuentra el punto donde la experiencia deja de ser aceptable.','Simulación','~25 h',25,array['Redes','Simulación','Sistemas complejos']::text[],array['crear','investigar','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria de software ingenieria industrial telecomunicaciones matematica estadistica computacion e informatica modelamiento y simulacion. conceptos de ancho de banda. analisis de resultados. pensamiento sistemico. comunicacion de supuestos. hoja de calculo. software de simulacion o un lenguaje de programacion sencillo. herramienta para hacer graficos.',$f8dab31${"id": "cien-personas-en-la-misma-red-que-pasa-con-la-velocidad", "area": "tecnologia", "areas2": ["ciencias"], "titulo": "Cien personas en la misma red: ¿qué pasa con la velocidad?", "resumen": "Simula qué ocurre con la velocidad de una conexión cuando cada vez más personas la comparten, y encuentra el punto donde la experiencia deja de ser aceptable.", "tipo": "Simulación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Redes", "Simulación", "Sistemas complejos"], "intencion": ["crear", "investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: define tú los números de usuarios, de ancho de banda y de consumo para cada escenario.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Ingeniería Industrial", "Telecomunicaciones", "Matemática", "Estadística", "Computación e Informática"], "problema": ["En un salón, una biblioteca o una oficina, la conexión funciona bien con pocas personas y se vuelve lenta de golpe cuando llegan muchas. Casi nadie sabe por qué ocurre ni cuántos usuarios soporta realmente una red.", "Sin una forma de estimarlo, las decisiones se toman por intuición: se contrata más ancho de banda sin comprobar si el problema era ese."], "desarrollar": ["Modela una red sencilla con una conexión total y un grupo de usuarios que hacen actividades distintas: navegar, ver videos, descargar archivos. Define cuánto consume cada actividad y simula qué ocurre cuando el grupo crece de 10 a 100 personas.", "Mide en cada escenario cuánto le toca a cada usuario y cuándo una actividad deja de funcionar bien. El resultado puede ser un modelo en hoja de cálculo o un programa de simulación, con un gráfico que muestre el punto de quiebre."], "ampliaciones": [{"titulo": "Horas pico", "aporta": "haz que los usuarios no conecten al mismo tiempo sino siguiendo un horario realista y compara con el caso constante."}, {"titulo": "Una regla de reparto", "aporta": "prueba qué cambia si se limita el consumo de las descargas para proteger las videollamadas."}, {"titulo": "Dos redes en una", "aporta": "simula una oficina con dos conexiones y estudia cuándo conviene dividir a los usuarios."}], "objetivos": ["Representar una red compartida con un modelo sencillo.", "Definir supuestos de consumo por tipo de actividad.", "Ejecutar escenarios con distinta cantidad de usuarios.", "Identificar el punto en que la calidad deja de ser aceptable.", "Comunicar el resultado y sus límites."], "habilidades": ["Modelamiento y simulación.", "Conceptos de ancho de banda.", "Análisis de resultados.", "Pensamiento sistémico.", "Comunicación de supuestos."], "herramientas": ["Hoja de cálculo.", "Software de simulación o un lenguaje de programación sencillo.", "Herramienta para hacer gráficos."], "lineamientos": ["Declara siempre tus supuestos: los resultados valen solo para esos números y no para cualquier red real.", "Si quieres contrastar con una red real, hazlo solo con la tuya o con permiso de quien la administre."], "otroSector": "La misma estructura sirve para estudiar atención en ventanillas, uso de un ascensor, capacidad de un servidor o demanda sobre un recurso compartido cualquiera."}$f8dab31$::jsonb,22),
('por-que-cuesta-usar-algunas-aplicaciones-un-rediseno-paso-a-paso','tecnologia',array['sociedad','arte']::text[],'¿Por qué cuesta usar algunas aplicaciones? Un rediseño paso a paso','Observa dónde se confunde una persona al usar una aplicación, página o formulario, y propón un rediseño que lo haga más claro.','Prototipo','~25 h',25,array['Experiencia de usuario','Diseño','Usabilidad']::text[],array['crear','resolver','otro-sector']::text[],'propios','sin','ingenieria de sistemas ingenieria de software diseno grafico psicologia comunicaciones educacion arquitectura computacion e informatica diseno web experiencia de usuario. observacion y entrevistas breves. diseno de interfaces. redaccion de mensajes claros. evaluacion de resultados. papel y lapiz o una herramienta de diseno. documento para registrar las observaciones. herramienta de prototipos.',$fb60e17${"id": "por-que-cuesta-usar-algunas-aplicaciones-un-rediseno-paso-a-paso", "area": "tecnologia", "areas2": ["sociedad", "arte"], "titulo": "¿Por qué cuesta usar algunas aplicaciones? Un rediseño paso a paso", "resumen": "Observa dónde se confunde una persona al usar una aplicación, página o formulario, y propón un rediseño que lo haga más claro.", "tipo": "Prototipo", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Experiencia de usuario", "Diseño", "Usabilidad"], "intencion": ["crear", "resolver", "otro-sector"], "datos": "propios", "datosTexto": "propios o ficticios: puedes elegir una aplicación o página cotidiana y observar a personas usándola, con su permiso, o trabajar con un caso inventado.", "prog": "sin", "progTexto": "Sin programación: se puede hacer completo con documentos y hoja de cálculo.", "carreras": ["Ingeniería de Sistemas", "Ingeniería de Software", "Diseño Gráfico", "Psicología", "Comunicaciones", "Educación", "Arquitectura", "Computación e Informática", "Diseño Web"], "problema": ["Hay aplicaciones y páginas que funcionan bien para quien las diseñó pero resultan confusas para casi todos los demás: botones que no se entienden, páginas sin instrucciones o formularios que fallan después de haberlos llenado.", "Cuando una persona se equivoca, suele culparse a sí misma, aunque el problema sea del diseño. Esto afecta más a personas mayores y a quienes usan poco la tecnología."], "desarrollar": ["Elige una aplicación, una página o un formulario que haya causado problemas y pídele a tres personas que lo usen para una tarea concreta mientras tú observas sin ayudarlas. Anota dónde dudan, qué errores cometen y qué comentan.", "Con lo observado, redibuja las pantallas más problemáticas en papel o con una herramienta de diseño y prueba el nuevo diseño con las mismas personas. El resultado puede ser un antes y un después con las mejoras que más ayudaron."], "ampliaciones": [{"titulo": "Una página sin instrucciones", "aporta": "rediseña una pantalla que hoy exige adivinar qué hacer y agrégale el texto de ayuda que falta."}, {"titulo": "Un formulario que avisa a tiempo", "aporta": "diseña un formulario que detecte los errores antes de enviarlo y los explique con claridad."}, {"titulo": "Una lista de reglas", "aporta": "resume tus hallazgos en cinco recomendaciones que puedan servir a cualquier diseñador."}], "objetivos": ["Observar a personas usando una interfaz sin intervenir.", "Identificar los puntos donde se confunden y por qué.", "Proponer cambios concretos y justificarlos.", "Probar el rediseño con las mismas personas.", "Presentar las mejoras con ejemplos visuales."], "habilidades": ["Experiencia de usuario.", "Observación y entrevistas breves.", "Diseño de interfaces.", "Redacción de mensajes claros.", "Evaluación de resultados."], "herramientas": ["Papel y lápiz o una herramienta de diseño.", "Documento para registrar las observaciones.", "Herramienta de prototipos."], "lineamientos": ["Cuidados: pide permiso a cada persona que observes y explícale que se evalúa la aplicación y no su habilidad. No grabes ni publiques datos que la identifiquen.", "No copies el diseño de una aplicación protegida: propone mejoras con tus propias ideas."], "otroSector": "El mismo método sirve para mejorar carteles, trámites, instrucciones de un electrodoméstico, menús de un restaurante o señalización de un lugar público."}$fb60e17$::jsonb,23),
('y-si-los-datos-llegan-tarde-decidir-con-informacion-atrasada','tecnologia',array['industria','negocios']::text[],'¿Y si los datos llegan tarde? Decidir con información atrasada','Simula cómo se deterioran las decisiones automáticas cuando la información que reciben llega con retraso.','Simulación','~25 h',25,array['Datos','Simulación','Decisiones']::text[],array['crear','investigar','otro-sector']::text[],'ficticios','opcional','ingenieria de sistemas ingenieria industrial ingenieria de software administracion matematica computacion e informatica logistica modelamiento y simulacion. pensamiento sistemico. control y retroalimentacion. analisis de resultados. comunicacion clara. hoja de calculo. software de simulacion o programacion sencilla. herramienta de graficos.',$fca6fe1${"id": "y-si-los-datos-llegan-tarde-decidir-con-informacion-atrasada", "area": "tecnologia", "areas2": ["industria", "negocios"], "titulo": "¿Y si los datos llegan tarde? Decidir con información atrasada", "resumen": "Simula cómo se deterioran las decisiones automáticas cuando la información que reciben llega con retraso.", "tipo": "Simulación", "tiempo": "~25 h", "horas": 25, "etiquetas": ["Datos", "Simulación", "Decisiones"], "intencion": ["crear", "investigar", "otro-sector"], "datos": "ficticios", "datosTexto": "ficticios: simula un proceso con números inventados, como el stock de una tienda o la temperatura de un cuarto.", "prog": "opcional", "progTexto": "Programación opcional: puedes empezar sin programar y sumarla si quieres ir más lejos.", "carreras": ["Ingeniería de Sistemas", "Ingeniería Industrial", "Ingeniería de Software", "Administración", "Matemática", "Computación e Informática", "Logística"], "problema": ["Muchos sistemas actúan según los datos que reciben: reponer inventario, encender un ventilador o avisar que se acaba un producto. Si esos datos llegan con minutos, horas o días de retraso, el sistema decide sobre una realidad que ya cambió.", "El resultado son pedidos de más o de menos, alarmas tardías y oscilaciones: se corrige un problema que ya pasó y se crea otro nuevo."], "desarrollar": ["Modela un proceso simple, como una tienda que repone productos según su stock, y simula una semana de operación con datos al instante. Luego añade retrasos de una hora, medio día y un día entero, y mide cuánto empeora cada indicador: faltantes, excesos y costos.", "Compara los escenarios con una tabla y un gráfico, y propón una regla que reduzca el daño del retraso. El resultado puede ser un modelo en hoja de cálculo con una conclusión clara."], "ampliaciones": [{"titulo": "Qué retraso se tolera", "aporta": "encuentra el límite a partir del cual el sistema deja de ser útil."}, {"titulo": "Una regla más prudente", "aporta": "compara decidir con el último dato con decidir con un promedio de varios."}, {"titulo": "Un sistema real", "aporta": "aplica la idea a una cadena de suministro o a un sistema de riego, con sus datos propios."}], "objetivos": ["Modelar un proceso que reacciona a datos.", "Simular distintos retrasos de información.", "Medir el efecto en indicadores clave.", "Proponer reglas que reduzcan el daño.", "Comunicar el resultado con gráficos."], "habilidades": ["Modelamiento y simulación.", "Pensamiento sistémico.", "Control y retroalimentación.", "Análisis de resultados.", "Comunicación clara."], "herramientas": ["Hoja de cálculo.", "Software de simulación o programación sencilla.", "Herramienta de gráficos."], "lineamientos": ["Declara los supuestos del modelo y evita generalizar sus resultados a casos reales sin comprobarlos.", "Si lo aplicas a un negocio verdadero, pide permiso y no publiques sus cifras."], "otroSector": "Esta idea sirve para estudiar semáforos, calefacción, riego automático, pedidos de un restaurante o cualquier proceso donde la información tarda en llegar."}$fca6fe1$::jsonb,24)
